mapper.select:
SELECT m.game_end_time as game_end_time, m.account as account, c.platform_name as platform_name , c.son_platform_name as son_platform_name, FORMAT(sum(m.cell_score),2) as sumCellScore, FORMAT(SUM(m.all_bet),2) as sumAllBet , FORMAT(SUM(m.profit),2) as sumProfit, FORMAT(-SUM(m.profit),2) as sumPlatformProfit FROM member_game_data m left join config_gametype c on m.agent = c.platform_id AND m.kind_id = c.son_platform_id and m.cell_score <> ('0.00')
and m.cell_score <> ('0.00')
and m.account =#{req.account}
and c.son_platform_name =#{req.son_platform_name}
and m.game_end_time >= #{req.pubStartDate} and m.game_end_time <= #{req.pubEndDate}
GROUP BY m.account, c.platform_name, c.son_platform_name ORDER BY CONVERT(sum(m.cell_score), DECIMAL) desc
